Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<p id="demoNarration" style="margin:0;font-size:10px;max-width:180px"></p>
<span style="white-space:nowrap"><button onclick="prevStep()">◀</button> <span id="stepLabel" style="font-size:10px"></span> <button onclick="nextStep()">▶</button></span>
<label>Threshold n0: <output id="thresholdN0Val">30</output><input id="thresholdN0Input" type="range" min="0" max="100" step="1" value="30" oninput="document.getElementById('thresholdN0Val').value=this.value;update_thresholdN0(+this.value)"></label>
<label>Constant multiplier c: <output id="constantMultiplierVal">1.5</output><input id="constantMultiplierInput" type="range" min="0.5" max="2.5" step="0.1" value="1.5" oninput="document.getElementById('constantMultiplierVal').value=(+this.value).toFixed(1);update_constantMultiplier(+this.value)"></label>
<label>Notation <select id="notationViewInput" onchange="update_notationView(this.value)"><option selected>Θ — two-sided</option><option>O — upper only</option><option>Ω — lower only</option></select></label>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var state = { n0: 30, c: 1.5, notation: 'Θ — two-sided', emphasized: false };

/* ── Curves (world coordinates: n in [0,100]) ─────────────────────────── */
/* g(n) has a gentle upward curvature so the constant-rescaled bounds fan
   out as visible curves rather than near-straight lines. f(n) oscillates
   only in the pre-settling region: the wiggle amplitude decays as
   exp(-n/12), so by n ≈ 45 the function is smooth and monotone, exactly
   the "settles down right of n₀" look of the source figure. */
function g(n) { return 10 + 0.28 * n + 0.0042 * n * n; }
function settle(n) { return Math.exp(-n / 12); }
function fTheta(n) { return g(n) * (1.10 + 1.5 * settle(n) * Math.sin(1.1 * n + 3.14)); }
function fO(n)     { return g(n) * (0.92 + 1.0 * settle(n) * Math.sin(1.4 * n + 2.5)); }
function fW(n)     { return g(n) * (1.06 + 0.85 * settle(n) * Math.sin(1.3 * n + 1.0)); }

var NOTATION_KEYS = { 'Θ — two-sided': 'theta', 'O — upper only': 'bigO', 'Ω — lower only': 'omega' };

var PANELS = [
  {
    key: 'theta', tag: '(a)', caption: 'f(n) = Θ(g(n))', f: fTheta,
    curveLabels: [{ id: 'upper', t: 'c₂g(n)' }, { id: 'f', t: 'f(n)' }, { id: 'lower', t: 'c₁g(n)' }],
    popup: 'f(n) = Θ(g(n)) means there exist constants c₁, c₂ > 0 and a threshold n₀ so that c₁g(n) ≤ f(n) ≤ c₂g(n) for every n ≥ n₀. The shaded corridor is the only region f(n) must stay in — any misbehavior before the dashed line is simply ignored.'
  },
  {
    key: 'bigO', tag: '(b)', caption: 'f(n) = O(g(n))', f: fO,
    curveLabels: [{ id: 'ceil', t: 'cg(n)' }, { id: 'f', t: 'f(n)' }],
    popup: 'f(n) = O(g(n)) means some constant c and threshold n₀ give f(n) ≤ cg(n) for all n ≥ n₀. f(n) may dip arbitrarily far below the ceiling and still satisfy O — only escaping above cg(n) to the right of n₀ breaks the bound.'
  },
  {
    key: 'omega', tag: '(c)', caption: 'f(n) = Ω(g(n))', f: fW,
    curveLabels: [{ id: 'f', t: 'f(n)' }, { id: 'floor', t: 'cg(n)' }],
    popup: 'f(n) = Ω(g(n)) means some constant c > 0 and threshold n₀ give f(n) ≥ cg(n) for all n ≥ n₀. f(n) may soar arbitrarily far above the floor — only dipping below cg(n) to the right of n₀ breaks the bound.'
  }
];

function violates(p, n) {
  if (n < state.n0 - 1e-9) return false;
  var fv = p.f(n), gv = g(n), c = state.c;
  if (p.key === 'theta') return fv > c * gv + 1e-9 || fv < gv / c - 1e-9;
  if (p.key === 'bigO') return fv > c * gv + 1e-9;
  return fv < c * gv - 1e-9;
}

function fDataset(p, fData, active) {
  return {
    id: 'f', data: fData, borderColor: '#222', borderWidth: 2, pointRadius: 0,
    segment: {
      borderColor: function (ctx) {
        if (!active) return '#222';
        var n = (fData[ctx.p0DataIndex].x + fData[ctx.p1DataIndex].x) / 2;
        return violates(p, n) ? '#d62728' : '#222';
      },
      borderWidth: function (ctx) {
        if (!active) return 2;
        var n = (fData[ctx.p0DataIndex].x + fData[ctx.p1DataIndex].x) / 2;
        return violates(p, n) ? 3 : 2;
      }
    }
  };
}

function buildData(p, active) {
  var c = state.c, n0 = state.n0, i, gv;
  var fData = [], ds = [], ymax = 0;
  for (i = 0; i <= 100; i++) { fData.push({ x: i, y: p.f(i) }); if (fData[i].y > ymax) ymax = fData[i].y; }
  if (p.key === 'theta') {
    var up = [], lo = [], upS = [], loS = [];
    for (i = 0; i <= 100; i++) {
      gv = g(i);
      up.push({ x: i, y: c * gv }); lo.push({ x: i, y: gv / c });
      if (c * gv > ymax) ymax = c * gv;
      if (i >= n0) { upS.push({ x: i, y: c * gv }); loS.push({ x: i, y: gv / c }); }
    }
    if (active) {
      ds.push({ id: 'shadeLo', data: loS, borderWidth: 0, pointRadius: 0 });
      ds.push({ id: 'shadeHi', data: upS, borderWidth: 0, pointRadius: 0, fill: '-1', backgroundColor: 'rgba(90,171,240,0.22)' });
    }
    ds.push({ id: 'lower', data: lo, borderColor: '#222', borderWidth: 1.4, pointRadius: 0 });
    ds.push({ id: 'upper', data: up, borderColor: '#222', borderWidth: 1.4, pointRadius: 0 });
  } else if (p.key === 'bigO') {
    var ceil = [], ceilS = [];
    for (i = 0; i <= 100; i++) {
      gv = g(i); ceil.push({ x: i, y: c * gv });
      if (c * gv > ymax) ymax = c * gv;
      if (i >= n0) ceilS.push({ x: i, y: c * gv });
    }
    if (active) ds.push({ id: 'shade', data: ceilS, borderWidth: 0, pointRadius: 0, fill: 'origin', backgroundColor: 'rgba(90,171,240,0.22)' });
    ds.push({ id: 'ceil', data: ceil, borderColor: '#222', borderWidth: 1.4, pointRadius: 0 });
  } else {
    var fl = [], flS = [];
    for (i = 0; i <= 100; i++) {
      gv = g(i); fl.push({ x: i, y: c * gv });
      if (c * gv > ymax) ymax = c * gv;
      if (i >= n0) flS.push({ x: i, y: c * gv });
    }
    if (active) ds.push({ id: 'shade', data: flS, borderWidth: 0, pointRadius: 0, fill: 'end', backgroundColor: 'rgba(90,171,240,0.22)' });
    ds.push({ id: 'floor', data: fl, borderColor: '#222', borderWidth: 1.4, pointRadius: 0 });
  }
  ds.push(fDataset(p, fData, active));
  return { ds: ds, ymax: ymax * 1.10 + 3 };
}

/* ── Sketch-style overlay: L axes, arrow, dashed n0 line, curve labels ── */
function makeDrawPlugin(p) {
  return {
    id: 'sketch-' + p.key,
    afterDatasetsDraw: function (chart) {
      var ca = chart.chartArea; if (!ca) return;
      var xs = chart.scales.x, ys = chart.scales.y, ctx = chart.ctx;
      var x0 = xs.getPixelForValue(0), y0 = ys.getPixelForValue(0);
      var fs = Math.max(10, Math.min(14, Math.min(chart.width, chart.height) * 0.05));
      ctx.save();
      ctx.strokeStyle = '#222'; ctx.fillStyle = '#222'; ctx.lineWidth = 1.2; ctx.lineCap = 'round';
      ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x0, ca.top - 8); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(ca.right + 10, y0); ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(ca.right + 10, y0); ctx.lineTo(ca.right + 3, y0 - 3.5);
      ctx.moveTo(ca.right + 10, y0); ctx.lineTo(ca.right + 3, y0 + 3.5);
      ctx.stroke();
      var xn = xs.getPixelForValue(state.n0);
      var yTop = Math.max(ca.top + 2, ys.getPixelForValue(p.f(state.n0)) - 4);
      ctx.setLineDash([4, 4]);
      ctx.beginPath(); ctx.moveTo(xn, y0); ctx.lineTo(xn, yTop); ctx.stroke();
      ctx.setLineDash([]);
      ctx.beginPath(); ctx.moveTo(xn, y0 - 3); ctx.lineTo(xn, y0 + 3); ctx.stroke();
      ctx.font = 'italic ' + fs + 'px Georgia,"Times New Roman",serif';
      function halo(t, x, y, align) {
        ctx.textAlign = align || 'left'; ctx.textBaseline = 'alphabetic';
        ctx.lineWidth = 3; ctx.strokeStyle = 'rgba(255,255,255,0.9)';
        ctx.strokeText(t, x, y);
        ctx.fillStyle = '#222'; ctx.fillText(t, x, y);
        ctx.strokeStyle = '#222'; ctx.lineWidth = 1.2;
      }
      halo('n', ca.right + 9, y0 + fs + 2, 'center');
      if (state.n0 > 82) halo('n₀', xn - 6, y0 + fs + 2, 'right');
      else halo('n₀', xn, y0 + fs + 2, 'center');
      p.curveLabels.forEach(function (L) {
        var idx = -1, i;
        for (i = 0; i < chart.data.datasets.length; i++) if (chart.data.datasets[i].id === L.id) { idx = i; break; }
        if (idx < 0) return;
        var arr = chart.data.datasets[idx].data; if (!arr || !arr.length) return;
        var last = arr[arr.length - 1];
        halo(L.t, xs.getPixelForValue(last.x) + 6, ys.getPixelForValue(last.y) - 6, 'left');
      });
      ctx.restore();
    }
  };
}

/* ── Build DOM + charts ───────────────────────────────────────────────── */
var mainWrap = document.createElement('div');
mainWrap.style.cssText = 'display:flex;gap:10px;width:100%;height:100%;box-sizing:border-box;';
document.getElementById('container').appendChild(mainWrap);

function describe(p, n) {
  var nn = Math.round(n), c = state.c, gv = g(nn), fv = p.f(nn);
  var pre = 'n ≈ ' + nn + ' · ';
  if (nn < state.n0) return pre + 'before n₀ — asymptotic bounds ignore this region';
  if (p.key === 'theta') {
    if (fv > c * gv) return pre + 'f(n) above c₂g(n) — violation';
    if (fv < gv / c) return pre + 'f(n) below c₁g(n) — violation';
    return pre + 'f(n) inside the corridor c₁g(n)–c₂g(n)';
  }
  if (p.key === 'bigO') return pre + (fv > c * gv ? 'f(n) above the ceiling cg(n) — violation' : 'f(n) under the ceiling cg(n) — O holds here');
  return pre + (fv < c * gv ? 'f(n) below the floor cg(n) — violation' : 'f(n) above the floor cg(n) — Ω holds here');
}

PANELS.forEach(function (p) {
  var wrap = document.createElement('div');
  wrap.style.cssText = 'flex:1;display:flex;flex-direction:column;min-width:0;border-radius:4px;padding:2px;box-shadow:0 0 0 1px #e0e0e0;transition:opacity 0.3s ease;';
  var holder = document.createElement('div');
  holder.style.cssText = 'position:relative;flex:1;min-height:0;';
  var canvas = document.createElement('canvas');
  holder.appendChild(canvas); wrap.appendChild(holder);
  var cap = document.createElement('div');
  cap.style.cssText = 'text-align:center;font-family:Georgia,serif;font-style:italic;font-size:13px;line-height:1.35;';
  cap.textContent = p.caption;
  var tag = document.createElement('div');
  tag.style.cssText = 'text-align:center;font-family:Georgia,serif;font-size:12px;line-height:1.2;';
  tag.textContent = p.tag;
  wrap.appendChild(cap); wrap.appendChild(tag);
  mainWrap.appendChild(wrap);

  /* Default view shows all three panels unshaded at full contrast, matching
     the static source figure; shading/labels arrive once a view is chosen. */
  var built0 = buildData(p, false);
  var chart = new Chart(canvas.getContext('2d'), {
    type: 'line',
    data: { datasets: built0.ds },
    options: {
      responsive: true, maintainAspectRatio: false,
      animation: { duration: 400 },
      events: [],
      plugins: { legend: { display: false }, tooltip: { enabled: false } },
      layout: { padding: { right: 66, top: 16, left: 6, bottom: 20 } },
      scales: {
        x: { type: 'linear', min: 0, max: 100, display: false },
        y: { min: 0, max: built0.ymax, display: false }
      },
      elements: { line: { tension: 0.35, borderJoinStyle: 'round', borderCapStyle: 'round' }, point: { radius: 0 } }
    },
    plugins: [makeDrawPlugin(p)]
  });
  p.chart = chart; p.wrap = wrap; p.canvas = canvas;

  canvas.style.cursor = 'pointer';
  canvas.addEventListener('mousemove', function (e) {
    var ca = chart.chartArea; if (!ca) return;
    var rect = canvas.getBoundingClientRect();
    var x = e.clientX - rect.left, y = e.clientY - rect.top;
    if (x < ca.left || x > ca.right || y < ca.top || y > ca.bottom) { hideTooltip(); return; }
    showTooltip(describe(p, chart.scales.x.getValueForPixel(x)), e);
  });
  canvas.addEventListener('mouseleave', hideTooltip);
  canvas.addEventListener('click', function () { showPopup(p.caption, p.popup); });
});

function refresh() {
  var activeKey = NOTATION_KEYS[state.notation];
  PANELS.forEach(function (p) {
    var on = (p.key === activeKey);
    /* Shading/violation highlighting appears once a view is emphasized
       (user interacted or a demo step is active); before that every panel
       renders plain and full-contrast like the source figure. */
    var showRegion = state.emphasized && on;
    var built = buildData(p, showRegion);
    p.chart.data.datasets = built.ds;
    p.chart.options.scales.y.max = built.ymax;
    p.chart.update();
    p.wrap.style.opacity = (!state.emphasized || on) ? '1' : '0.35';
    p.wrap.style.boxShadow = (state.emphasized && on) ? '0 0 0 2px #5aabf0' : '0 0 0 1px #e0e0e0';
  });
}

/* ── Controls ─────────────────────────────────────────────────────────── */
function update_thresholdN0(v) { state.n0 = v; if (state.emphasized) refresh(); else refresh(); }
function update_constantMultiplier(v) { state.c = v; refresh(); }
function update_notationView(v) { state.notation = v; state.emphasized = true; refresh(); }

/* ── Demo step player ─────────────────────────────────────────────────── */
var demoSteps = [
  { title: 'Θ: a two-sided corridor', narration: 'In panel (a), f(n) is sandwiched between c₁g(n) and c₂g(n) for all n ≥ n₀; the shaded corridor is the region f(n) must stay in once n passes the dashed line.', state: { notationView: 'Θ — two-sided', thresholdN0: 30, constantMultiplier: 1.5 } },
  { title: 'Push n0 into the messy region', narration: 'Drag n₀ left and red violation marks appear where the early oscillations of f(n) escape the corridor — showing that bounds fail if the threshold is set before the function settles down.', state: { notationView: 'Θ — two-sided', thresholdN0: 8, constantMultiplier: 1.5 } },
  { title: 'Constants are negotiable', narration: 'Widening the multiplier restores the bound even at that early n₀: any sufficiently large c₂ (and small c₁) works, which is exactly why asymptotic notation absorbs constant factors.', state: { notationView: 'Θ — two-sided', thresholdN0: 8, constantMultiplier: 2.4 } },
  { title: 'O: an upper ceiling only', narration: 'Panel (b) shades everything below cg(n): f(n) may dip far under the ceiling and still satisfy O — only escaping above it to the right of n₀ counts as a violation.', state: { notationView: 'O — upper only', thresholdN0: 30, constantMultiplier: 1.5 } },
  { title: 'Ω: a lower floor only', narration: 'Panel (c) flips the comparison: with c < 1, cg(n) is a floor and f(n) may soar arbitrarily above it — only dipping below the floor past n₀ violates Ω.', state: { notationView: 'Ω — lower only', thresholdN0: 30, constantMultiplier: 0.7 } }
];
var currentStep = 0;

function applyStep(i) {
  currentStep = i;
  var s = demoSteps[i];
  state.n0 = s.state.thresholdN0;
  state.c = s.state.constantMultiplier;
  state.notation = s.state.notationView;
  /* Step 0 is the plain source-faithful view; later steps emphasize the
     active panel with shading and dimming. */
  state.emphasized = (i > 0);
  document.getElementById('thresholdN0Input').value = state.n0;
  document.getElementById('thresholdN0Val').value = state.n0;
  document.getElementById('constantMultiplierInput').value = state.c;
  document.getElementById('constantMultiplierVal').value = (+state.c).toFixed(1);
  document.getElementById('notationViewInput').value = state.notation;
  refresh();
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (i + 1) + '/' + demoSteps.length + ' · ' + s.title;
}
function prevStep() { if (currentStep > 0) applyStep(currentStep - 1); }
function nextStep() { if (currentStep < demoSteps.length - 1) applyStep(currentStep + 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

